function outer() {
  const outerVar = 'I am outer'; // \u5C40\u90E8\u53D8\u91CF

  function inner() {
    const innerVar = 'I am inner'; // \u5C40\u90E8\u53D8\u91CF
    console.log(globalVar); // I am global
    console.log(outerVar); // I am outer
    console.log(innerVar); // I am inner
  }

  inner();
}
outer();
