  static getDerivedStateFromProps(nextProps, prevState) {
    // nextProps: \u5373\u5C06\u66F4\u65B0\u7684 props
    // prevState: \u4E0A\u4E00\u4E2A\u72B6\u6001\u7684 state , 
    if (nextProps.count !== prevState.count) {
      return {
        count: nextProps.count
      };
    }
    return null; // \u8FD4\u56DE null \u8868\u793A state \u4E0D\u9700\u8981\u66F4\u65B0
  }
