function createWindow() {
  const mainWindow = new BrowserWindow({
    width: 800,
    height: 600,
    autoHideMenuBar: true, // \u9690\u85CF\u83DC\u5355\u680F
    // x:0, // \u8BBE\u7F6E\u7A97\u53E3\u4F4D\u7F6E
    // y:0,
    alwaysOnTop: true, // \u7A97\u53E3\u7F6E\u9876
  });

  // \u52A0\u8F7D \u672C\u5730index.html
  mainWindow.loadFile('src/pages/Home/index.html');
  // \u52A0\u8F7D \u7F51\u9875
  // mainWindow.loadURL('http://baidu.com')
}
