set = new Set([...set].map(x => x * 2)); // Set(3)\xA0{2, 4, 6}

let set = new Set([1, 2, 3, 4, 5]);
set = new Set([...set].filter(x => (x % 2) == 0)); // Set(2)\xA0{2, 4}

const a = new Set([1, 2, 3]);
const b = new Set([4, 3, 2]);

// \u5E76\u96C6
const union = new Set([...a, ...b]); // Set(4)\xA0{1, 2, 3, 4}

// \u4EA4\u96C6
const intersect = new Set([...a].filter(x => b.has(x))); // Set(2)\xA0{2, 3}

// \u5DEE\u96C6
const difference = new Set([...a].filter(x => !b.has(x))); // Set(1)\xA0{1}

