const map = new Map()
  .set(1, 'a')
  .set('2', 'b')
  .set({'ff': 1}, 'c')
  .set(Symbol('ee'), 'd')
  .set(hello, 'Hello ES6!'); 
// Map(4) {1 => 'a', '2' => 'b', {'ff': 1} => 'c', Symbol(ee) => 'd', function() {console.log('hello');} => "Hello ES6!"}

map.get(hello);  // Hello ES6!
map.delete('2'); // true
map.has('2'); // false
map.size; // 4
