\u8FD9\u79CD\u60C5\u51B5\u6211\u4EEC\u7684\u65B9\u6848\u5C31\u662F\u9700\u8981\u5728\u8D85\u65F6\u65F6\u957F\u5185\u53D1\u9001\u5FC3\u8DF3\u5305\u3002`,paraId:21,tocIndex:9},{value:"\u5FC3\u8DF3\u68C0\u6D4B\u6B65\u9AA4\uFF1A",paraId:22,tocIndex:10},{value:"\u5BA2\u6237\u7AEF\u6BCF\u9694\u4E00\u4E2A\u65F6\u95F4\u95F4\u9694\u53D1\u751F\u4E00\u4E2A\u63A2\u6D4B\u5305\u7ED9\u670D\u52A1\u5668\uFF0C\u5E76\u542F\u52A8\u4E00\u4E2A\u8D85\u65F6\u5B9A\u65F6\u5668\u3002",paraId:23,tocIndex:10},{value:"\u670D\u52A1\u5668\u7AEF\u63A5\u6536\u5230\u68C0\u6D4B\u5305\uFF0C\u5E94\u8BE5\u56DE\u5E94\u4E00\u4E2A\u5305\u3002",paraId:23,tocIndex:10},{value:"\u5982\u679C\u5BA2\u6237\u673A\u6536\u5230\u670D\u52A1\u5668\u7684\u5E94\u7B54\u5305\uFF0C\u5219\u8BF4\u660E\u670D\u52A1\u5668\u6B63\u5E38\uFF0C\u5220\u9664\u8D85\u65F6\u5B9A\u65F6\u5668\u3002",paraId:23,tocIndex:10},{value:"\u5982\u679C\u5BA2\u6237\u7AEF\u7684\u8D85\u65F6\u5B9A\u65F6\u5668\u8D85\u65F6\uFF0C\u4F9D\u7136\u6CA1\u6709\u6536\u5230\u5E94\u7B54\u5305\uFF0C\u5219\u8BF4\u660E\u670D\u52A1\u5668\u6302\u4E86\u3002",paraId:23,tocIndex:10},{value:`// \u524D\u7AEF\u89E3\u51B3\u65B9\u6848\uFF1A\u5FC3\u8DF3\u68C0\u6D4B
var heartCheck = {
    timeout: 30000, //30\u79D2\u53D1\u4E00\u6B21\u5FC3\u8DF3
    timeoutObj: null,
    serverTimeoutObj: null,
    reset: function(){
        clearTimeout(this.timeoutObj);
        clearTimeout(this.serverTimeoutObj);
        return this;
    },
    start: function(){
        var self = this;
        this.timeoutObj = setTimeout(function(){
            //\u8FD9\u91CC\u53D1\u9001\u4E00\u4E2A\u5FC3\u8DF3\uFF0C\u540E\u7AEF\u6536\u5230\u540E\uFF0C\u8FD4\u56DE\u4E00\u4E2A\u5FC3\u8DF3\u6D88\u606F\uFF0C
            //onmessage\u62FF\u5230\u8FD4\u56DE\u7684\u5FC3\u8DF3\u5C31\u8BF4\u660E\u8FDE\u63A5\u6B63\u5E38
            ws.send("ping");
            console.log("ping!")

            self.serverTimeoutObj = setTimeout(function(){//\u5982\u679C\u8D85\u8FC7\u4E00\u5B9A\u65F6\u95F4\u8FD8\u6CA1\u91CD\u7F6E\uFF0C\u8BF4\u660E\u540E\u7AEF\u4E3B\u52A8\u65AD\u5F00\u4E86
                ws.close(); //\u5982\u679Conclose\u4F1A\u6267\u884Creconnect\uFF0C\u6211\u4EEC\u6267\u884Cws.close()\u5C31\u884C\u4E86.\u5982\u679C\u76F4\u63A5\u6267\u884Creconnect \u4F1A\u89E6\u53D1onclose\u5BFC\u81F4\u91CD\u8FDE\u4E24\u6B21
            }, self.timeout);
        }, this.timeout);
    }
}

