// \u76D1\u542C hashchange \u4E8B\u4EF6
window.addEventListener('hashchange', function() {
  var currentHash = window.location.hash;
  
  // \u6839\u636E\u4E0D\u540C\u7684\u54C8\u5E0C\u503C\u6267\u884C\u76F8\u5E94\u7684\u64CD\u4F5C
  if (currentHash === '#section1') {
      console.log('\u663E\u793A\u7B2C\u4E00\u90E8\u5206\u7684\u5185\u5BB9')
  } else if (currentHash === '#section2') {
      console.log('\u663E\u793A\u7B2C\u4E8C\u90E8\u5206\u7684\u5185\u5BB9')
  } else {
      console.log('\u5176\u4ED6\u64CD\u4F5C')
  }
});
